	@Test
	void preparationClonesPerSearchRatherThanPerCandidatePosition() {
		List<Filter> filters = new ArrayList<>();
		TupleExpr expression = values("x", 1, 2, 3);
		for (int i = 0; i < 6; i++) {
			ValueExpr nestedExists = new Exists(new Filter(values("x", 1), new Exists(values("x", 1))));
			Filter filter = new Filter(expression, nestedExists);
			filters.add(filter);
			expression = filter;
		}
		for (int i = 0; i < 18; i++) {
			expression = new Join(expression, values("y" + i, i));
		}
		AtomicInteger clones = new AtomicInteger();
		CountingQueryRoot root = new CountingQueryRoot(expression, clones);
		FilterPlacementAnalyzer analyzer = analyzer(root);
		for (Filter filter : filters) {
			Envelope envelope = analyzer.analyze(filter);
			assertThat(envelope.singletonAlternatives()).hasSizeGreaterThan(8);
			assertThat(alternatives(envelope)).hasSameSizeAs(envelope.singletonAlternatives());
		}
		assertThat(clones.get()).as("one generation snapshot and one scratch clone per independent search")
				.isLessThanOrEqualTo(1 + 2 * filters.size());
	}

	@Test
	void potentialSiteGraphCoversLazyUnionCutsWithoutProducts() {
		TupleExpr branches = new Join(values("observation", 1, 2), values("tail", 3));
		for (int i = 0; i < 3; i++) {
			branches = new Union(branches, branches.clone());
		}
		Filter filter = new Filter(new Join(values("prefix", 1), branches), new Bound(Var.of("observation")));
		AtomicInteger clones = new AtomicInteger();
		CountingQueryRoot root = new CountingQueryRoot(filter, clones);
		Envelope envelope = analyzer(root).analyze(filter);
		Set<TupleExpr> potential = envelope.potentialSites(argument -> true);
		Iterator<Alternative> alternatives = envelope.alternatives().iterator();
		for (int i = 0; i < 128 && alternatives.hasNext(); i++) {
			assertThat(potential).containsAll(arguments(alternatives.next()));
		}
		assertThat(potential).hasSizeGreaterThan(8);
		assertThat(clones.get()).as("one snapshot and one scratch clone per search or site graph")
				.isLessThanOrEqualTo(4);
		assertThatThrownBy(() -> potential.add(values("replacement", 0)))
				.isInstanceOf(UnsupportedOperationException.class);
	}

