	@Test
	void physicalAdmissionPrunesOpaqueUnionGraphsBeforeExpansion() {
		TupleExpr opaque = values("y", 1);
		for (int i = 0; i < 12; i++) {
			opaque = new Union(opaque, opaque.clone());
		}
		BindingSetAssignment anchor = values("x", 1);
		Join join = new Join(anchor, opaque);
		Filter filter = new Filter(join, new Bound(Var.of("x")));
		QueryRoot root = new QueryRoot(filter);
		Envelope envelope = analyzer(root).analyze(filter);
		Set<TupleExpr> admitted = Collections.newSetFromMap(new IdentityHashMap<>());
		admitted.add(join);
		admitted.add(anchor);
		admitted.add(opaque);
		TupleExpr inaccessible = ((Union) ((Union) opaque).getLeftArg()).getLeftArg();
		admitted.add(inaccessible);
		Set<TupleExpr> inspected = Collections.newSetFromMap(new IdentityHashMap<>());
		List<Alternative> catalog = new ArrayList<>();
		envelope.alternatives(argument -> {
			inspected.add(argument);
			return admitted.contains(argument);
		}).forEach(catalog::add);
		assertThat(catalog).hasSize(3).allSatisfy(alternative -> assertThat(alternative.cut()).hasSize(1));
		assertThat(catalog.stream().flatMap(a -> arguments(a).stream()).toList()).contains(join, anchor, opaque)
				.doesNotContain(inaccessible);
		assertThat(inspected).doesNotContain(inaccessible);
		inspected.clear();
		assertThat(envelope.potentialSites(argument -> {
			inspected.add(argument);
			return admitted.contains(argument);
		})).containsExactlyInAnyOrder(join, anchor, opaque);
		assertThat(inspected).doesNotContain(inaccessible);
	}

