	@Test
	void lazyCutsRetainTheirCapturedGenerationAfterARewrite() {
		BindingSetAssignment left = values("x", 1);
		BindingSetAssignment right = values("x", 2);
		Union union = new Union(left, right);
		Filter filter = new Filter(union, new Bound(Var.of("x")));
		QueryRoot root = new QueryRoot(filter);
		Envelope envelope = analyzer(root).analyze(filter);
		List<List<TupleExpr>> before = alternatives(envelope).stream()
				.map(FilterPlacementAnalyzerTest::arguments)
				.toList();
		filter.setArg(values("replacement", 3));
		union.setLeftArg(values("changed", 4));
		assertThat(envelope.isCurrent()).isFalse();
		List<List<TupleExpr>> after = alternatives(envelope).stream()
				.map(FilterPlacementAnalyzerTest::arguments)
				.toList();
		List<Alternative> admittedAfter = new ArrayList<>();
		envelope.alternatives(argument -> argument == union || argument == left || argument == right)
				.forEach(admittedAfter::add);
		assertThat(admittedAfter).hasSameSizeAs(after);
		assertThat(after).hasSameSizeAs(before);
		for (int i = 0; i < before.size(); i++) {
			assertThat(after.get(i)).hasSameSizeAs(before.get(i));
			for (int j = 0; j < before.get(i).size(); j++) {
				assertThat(after.get(i).get(j)).isSameAs(before.get(i).get(j));
			}
		}
	}

	@Test
	void earlyAndLateSeedsReachTheSamePositions() {
		BindingSetAssignment anchor = values("x", 1, 2);
		BindingSetAssignment suffix = values("y", 3, 4);
		Filter early = new Filter(anchor, new Bound(Var.of("x")));
		Join earlyJoin = new Join(early, suffix);
		QueryRoot earlyRoot = new QueryRoot(earlyJoin);
		FilterPlacementAnalyzer earlyAnalysis = analyzer(earlyRoot);
		assertThat(singletonSites(earlyAnalysis.analyze(early))).contains(anchor, suffix, earlyJoin)
				.doesNotContain(earlyRoot);
		assertThat(earlyAnalysis.transition(early, anchor, earlyJoin).legal()).isTrue();
		assertThat(earlyAnalysis.transition(early, earlyJoin, anchor).legal()).isTrue();

		BindingSetAssignment lateAnchor = values("x", 1, 2);
		BindingSetAssignment lateSuffix = values("y", 3, 4);
		Join lateJoin = new Join(lateAnchor, lateSuffix);
		Filter late = new Filter(lateJoin, new Bound(Var.of("x")));
		QueryRoot lateRoot = new QueryRoot(late);
		assertThat(singletonSites(analyzer(lateRoot).analyze(late)))
				.contains(lateAnchor, lateSuffix, lateJoin)
				.doesNotContain(lateRoot)
				.hasSize(3);
		assertEveryPlacementPreservesBag(earlyRoot, early, earlyAnalysis.analyze(early));
		assertEveryPlacementPreservesBag(lateRoot, late, analyzer(lateRoot).analyze(late));
	}

